INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Markt mit wenigen Anbietern immer ein Kartell?', 2, '[{"text": "Nein", "correct": true, "because": "Kartelle erfordern Absprachen"}, {"text": "Ja", "correct": false, "because": "Oligopole sind Marktformen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein typisches Merkmal eines Marktes mit wenigen großen Anbietern?', 3, '[{"text": "Reaktionsverbundenheit", "correct": true, "because": "Entscheidungen beeinflussen Konkurrenten"}, {"text": "Preisunabhängigkeit", "correct": false, "because": "Preise sind interdependent"}, {"text": "Keine Konkurrenz", "correct": false, "because": "Wettbewerb besteht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branchen zeigen oft eine Struktur mit wenigen Anbietern?', 5, '[{"text": "Mobilfunk", "correct": true, "because": "Wenige Netzbetreiber dominieren"}, {"text": "Flugzeugbau", "correct": true, "because": "Airbus und Boeing"}, {"text": "Friseursalons", "correct": false, "because": "Viele Anbieter"}, {"text": "Lebensmitteleinzelhandel", "correct": false, "because": "Nur teilweise oligopolistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Duopol ist ein Spezialfall mit zwei Anbietern. b) Ein solcher Markt garantiert hohe Preise.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Wettbewerb ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht immer wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich die Dynamik eines solchen Marktes analysiere?', 4, '[{"text": "Konkurrentenreaktionen", "correct": false, "because": "Kern der Interdependenz"}, {"text": "Markteintrittsbarrieren", "correct": false, "because": "Wichtig für Struktur"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Marktanalyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein solcher Markt immer homogene Produkte hat?', 2, '[{"text": "Nein", "correct": true, "because": "Kann homogen oder heterogen sein"}, {"text": "Ja", "correct": false, "because": "Produkte können variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten beobachte ich oft in einem Markt mit wenigen Anbietern?', 3, '[{"text": "Preisführerschaft", "correct": true, "because": "Ein Anbieter setzt Preise"}, {"text": "Preisunabhängigkeit", "correct": false, "because": "Preise sind gekoppelt"}, {"text": "Zufällige Preissetzung", "correct": false, "because": "Strategisch geplant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken bestehen in einem solchen Markt?', 5, '[{"text": "Preisabsprachen", "correct": true, "because": "Verstoßen gegen Kart: "Können Kartelle bilden"}, {"text": "Intensiver Wettbewerb", "correct": true, "because": "Fördert Innovation"}, {"text": "Hohe Preise", "correct": false, "because": "Nicht immer garantiert"}, {"text": "Marktaustritt", "correct": false, "because": "Eher selten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein solcher Markt führt oft zu Preiskämpfen. b) Er verhindert Innovationen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einen solchen Markt zu verstehen?', 4, '[{"text": "Wettbewerbsrecht", "correct": false, "because": "Relevant für Kartelle"}, {"text": "Marktanteile", "correct": false, "because": "Zeigen Dominanz"}, {"text": "Kundenzufriedenheit", "correct": true, "because": "Sekundär für Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein solcher Markt dasselbe wie ein Monopol?', 2, '[{"text": "Nein", "correct": true, "because": "Monopol hat einen Anbieter"}, {"text": "Ja", "correct": false, "because": "Oligopol hat wenige Anbieter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern die Bildung eines solchen Marktes?', 4, '[{"text": "Hohe Eintrittsbarrieren", "correct": true, "because": "Schützen bestehende Anbieter"}, {"text": "Skaleneffekte", "correct": true, "because": "Begünstigen große Firmen"}, {"text": "Niedrige Nachfrage", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Märkte immer stabil sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Wettbewerb kann instabil sein"}, {"text": "Ja", "correct": false, "because": "Preiskämpfe möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich in einem solchen Markt konkurriere?', 3, '[{"text": "Strategische Planung", "correct": true, "because": "Antizipiert Reaktionen"}, {"text": "Schnelle Expansion", "correct": false, "because": "Riskant ohne Strategie"}, {"text": "Manuelle Preissetzung", "correct": false, "because": "Zu reaktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Nachfrageoligopol hat wenige Käufer. b) Es führt immer zu niedrigen Preisen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strategien nutzen Anbieter in einem solchen Markt?', 5, '[{"text": "Produktdifferenzierung", "correct": true, "because": "Schafft Wettbewerbsvorteil"}, {"text": "Preisführerschaft", "correct": true, "because": "Beeinflusst Marktpreise"}, {"text": "Zufällige Werbung", "correct": false, "because": "Weniger effektiv"}, {"text": "Hohe Lagerbestände", "correct": false, "because": "Nicht primär strategisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem solchen Markt unwichtig?', 3, '[{"text": "Marktanteile", "correct": false, "because": "Zeigen Machtverhältnisse"}, {"text": "Konkurrenzverhalten", "correct": false, "because": "Kern der Dynamik"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein solcher Markt Innovation fördert?', 2, '[{"text": "Ja", "correct": true, "because": "Wettbewerb treibt Neuerungen"}, {"text": "Nein", "correct": false, "because": "Innovationen häufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gibt es in einem solchen Markt immer Preisabsprachen?', 3, '[{"text": "Nein", "correct": true, "because": "Absprachen sind illegal"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Markt mit wenigen Anbietern?', 4, '[{"text": "Mobilfunkmarkt mit drei Netzbetreibern", "correct": true, "because": "Typisches Angebotsoligopol"}, {"text": "Lokaler Gemüsemarkt", "correct": false, "because": "Viele Anbieter"}, {"text": "Staatliches Briefmonopol", "correct": false, "because": "Ein Anbieter"}]');
